func (r *raft) becomePreCandidate() {
  // TODO(xiangli) remove panic once raft is stable
  if r.state == StateLeader {
    panic("invalid transition [leader -> pre-candidate]")
  }
  // Changes step functions and state, but does not
  // increase r.Term or change r.Vote.
  r.step = stepCandidate
  r.trk.ResetVotes()
  r.tick = r.tickElection
  r.lead = None
  r.state = StatePreCandidate
  r.logger.Infof(
    "%x became pre-candidate at term %d",
    r.id, r.Term,
  )
}
